def render(self):
    try:
        tile = self.context.get_tile(self.tile_id)
    except ValueError:
        # requested tile does not exist
        self.request.response.setStatus(400)
        return u""
    return tile()

def render(self):
    if not all((self.tile_type, self.tile_id, self.uuids)):
        return u""

    tile = self.context.restrictedTraverse(self.tile_type)
    tile_instance = tile[self.tile_id]
    tile_instance.replace_with_uuids(self.uuids)
    return tile_instance()

def render(self):
    if "export-layout" in self.request and self.can_export_layout():
        name = self.request.get("layout-name", None)
        if name:
            layout = self.context.cover_layout

            registry = getUtility(IRegistry)
            settings = registry.forInterface(ICoverSettings)

            # Store name and layout as unicode.  Note that the
            # name must only contain ascii because it is used as
            # value for a vocabulary.
            if six.PY2:
                name = name.decode("ascii", "ignore")
                layout = layout.decode("utf-8")
            settings.layouts[name] = layout

    return self.index()

def render(self):
    if self.mode == interfaces.DISPLAY_MODE:
        return self.display_template(self)
    else:
        return self.input_template(self)
